import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/29-How-did-hackers-steal-your-lucky-money.html","title":"30-黑客是怎么偷走你压岁钱的？","lang":"zh-CN","frontmatter":{"title":"30-黑客是怎么偷走你压岁钱的？","icon":"read","date":"2025-04-25T22:25:21.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1745591514000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":5,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"3a296fb1bb050a6931bed646dee087ff73500518","time":1745591514000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Refactor code structure for improved readability and maintainability"},{"hash":"9ce3f18bd55b4496f61dc288cbe02cee98e4712d","time":1745590866000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft of \\"How did hackers steal your lucky money\\" article"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":8.7,"words":2611},"filePathRelative":"column/Programmingthinking/29-How-did-hackers-steal-your-lucky-money.md"}`),a={name:`29-How-did-hackers-steal-your-lucky-money.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>你肯定听说过或者在电影里看到过<strong>黑客</strong>吧？</p><p>只要给他们一台电脑，他们几乎能够做到任何事情，入侵路边的摄像头监控某个人、黑进银行系统转走别人的钱、甚至去军队的系统里偷取信息。</p><p>确实，黑客这个名字听起来就像是躲在暗中搞破坏的人。但其实，黑客这个词，是从<strong>hacker</strong>翻译过来的，有很多精通编程的计算机高手都自称hacker，所以，黑客并不一定都是坏人。而且，你可能想不到，都有很多黑客在保护我们的信息安全。</p><p>那这一讲，我就来给你聊聊神秘的黑客。在说的时候，我还会告诉你<strong>三条信息安全秘籍</strong>，帮你对付坏蛋黑客。</p><figure><img src="/assets/123e56dd81a3ef145da23e3d500c99c7-LdjlYFiz.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你肯定知道，无论是银行、QQ、微信还是各种游戏、外卖软件，都有账号密码，这个账号就相当于是你的房间，密码就是你房间的钥匙。</p><p>坏蛋黑客们最常干的一类事，就是登录你的账号，盗取你的信息。如果登录的是你银行账号，说不定会把你的压岁钱全都偷走，是不是很可恶？</p><p>那黑客是怎么入侵别人系统的呢？最简单的入侵方法，叫做暴力破解。说白了就是拿字母和数字一个个去试。</p><p>假如是纯数字组成的<strong>6位密码</strong>，理论上只有<strong>100万种</strong>可能性，黑客运气再差也只用试100万次就可以破解了。试100万次听起来挺多的，但对于现代计算机的运算能力来说，这简直是小菜一碟。黑客破解6位数字的密码，要不了<strong>0.1秒</strong>，比你眨眼的时间还短。</p><p>但如果你用的是<strong>6位字母和数字组合</strong>呢，黑客也只需要<strong>5秒钟</strong>左右就能破解。当然了，你要是用<strong>12位的字母和数字组合</strong>，计算机就得花上<strong>几千年</strong>时间才能破解，这几乎是不可能的。</p><p>这里，我就要告诉你<strong>第一个信息安全小秘籍</strong>了，<strong>你在设置密码的时候，要设置得尽可能长一些，并且要用数字和大小写字母要混用</strong>，这样一来，黑客很难用暴力破解试出你的密码。</p><figure><img src="/assets/d468e54675fcb3522f33d4c2dc98a216-C52RXC_a.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>另外，黑客破解密码的时候，还有一个密码库，里面记录着特别常见的密码，什么123456789，abcd1234，这一类的密码虽然也比较长，但黑客破解的时候会优先尝试这些密码，破解它们也用不了1秒钟时间，所以这样的密码最好也不要用。</p><p>当然了，对于暴力破解，很多公司都有应对措施。比如说银行吧，虽然银行卡密码只有6位数，黑客眨眼间就能破解，但只要你的账号<strong>连续输错3次或者5次</strong>密码，银行就会发现异常，把你的账户锁住，必须你本人去才可以解锁。</p><p>还有苹果手机的开机密码，如果总是输错，手机就会<strong>锁定</strong>一段时间。要是再输错，这个锁定时间就会增加时间，这样一来，黑客就没法通过暴力破解的方式入侵了。</p><p>当然了，除了一个一个试，黑客还有其他破解方法。</p><p>咱们前面说了，现在几乎各种网站、App都要注册账号。但一些小公司因为技术有限，系统安全等级很低，黑客可以轻松入侵他们的数据库，直接盗取你的账号密码。</p><p>但是，这不是他们的主要目的。在拿到账号密码之后，黑客会用这个账号密码去其他网站上碰运气，如果你所有的网站账号密码都是一样的，那你可就要遭殃了。</p><p>这里，就是我要给你的<strong>第二个安全小秘籍</strong>了：<strong>不要在所有的平台用同一个账号密码。</strong>如果你怕账号密码太多了记不住，我教你一个方法，你可以只记两组账号密码。像银行、微信等等和金钱有关的平台，用一组账号密码，这些平台安全级别比较高，黑客不容易入侵。</p><p>其他不重要的平台，用另一套账号密码注册，就算是这些账号密码泄露了，也不会对你造成太大影响。</p><p>不过，还有些黑客，既不用入侵数据库，也不用一个个地试，他们就会让你自己输入账号和密码。他们是怎么做到的呢？</p><figure><img src="/assets/2b95f8c3faf762f6ed162fe6368f9844-aAsxLz1s.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>他们会给你发邮件或者是短信，在邮件和短信附带一个链接，告诉你的银行卡密码泄露了，赶紧去链接修改密码。</p><p>如果你真的去这些链接里修改密码，那你就中计了。这个链接是假的，而你在这个链接里的所有操作都会被记录下来，黑客就拿到了你的银行卡卡号和密码。</p><p>这里，我再给你<strong>第三个安全秘籍</strong>：<strong>如果要修改账号密码，要去银行自己的App或者是官网上修改，不要轻易点开短信或者是邮箱里的链接。</strong></p><p>当然了，随着技术进步，很多平台也用上了更厉害的防护措施，阻挡黑客。比如需要用指纹或者面部识别来解锁。对黑客来说，这两样东西可不好偷了，总不能把你的脸或者手偷走吧？</p><p>不过，黑客们可都是找漏洞高手，只要安全系统里有漏洞，他们就能钻上空子。就连先进的<strong>人工智能技术</strong>也不例外。</p><p>我先请你一看音频封面。封面上这两张图片怎么看都是熊猫对吧？但是，一个专门用来识别图像的人工智能，看左边的照片也认为是熊猫，但看右边的照片却认为是长臂猿。这是怎么回事呢？</p><figure><img src="/assets/af93e5741a3963dc6588ba1b49454af7-C1lJYd2G.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>其实，右边的照片里增加了一些细微的<strong>背景干扰</strong>，这些干扰用人类的眼睛是识别不出来的，但是却会干扰人工智能的判断，这就是图像识别算法上的漏洞。</p><p>利用这种漏洞，黑客可以继续入侵我们的账户。比方说，世界上有一个比赛，叫做“<strong>国际安全极客大赛</strong>”。2019年的这个比赛上，大家挑战的项目就是欺骗图像识别的人工智能算法。比方说给小明的照片做处理，人工智能就会把小明当成小红。</p><p>如果黑客掌握了这种技术，就可能在其他人的照片或者是视频片段里冒充成你，入侵你的账户。</p><p>另外，还有些科学家发现了人工智能技术的另一项漏洞。比如，我在音频封面上给你展示了一张图片，图上怎么看都有两个人对吧？</p><figure><img src="/assets/1a22db0e64745644cd40989a71bed4c9-CVph18NT.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>但对人工智能来说，它<strong>只能识别出左边的人</strong>。这是因为，右边人的腰上贴了一张特殊的图片，这张图片会干扰人工智能的判断。</p><p>想象一下，咱们要是在银行金库装好多好多摄像头，这些摄像头能够识别画面里的物体，只要发现了人类，就发出报警。这时候，只要贴上这么一张图片，就好像贴了隐身符一样，就算你把金库搬个金光摄像头也不会有任何反应。</p><p>听到这儿你是不是有点担心，即便是人工智能技术都有漏洞，那在黑客面前，我们要怎么办呢？</p><p>别着急，你还记得我开头说的吧，在我们生活中，不是所有的黑客都是坏蛋。还有一些黑客，叫做<strong>白帽黑客</strong>，他们都是顶尖的编程高手。</p><p>很多公司会雇佣白帽黑客来攻击自己的系统，帮助自己找到系统漏洞，打上补丁，保护我们的信息安全。还有些机构会雇佣白帽黑客，搜集坏人的信息，找到他们犯罪的证据。像前面说的参加国际安全极客大赛的参赛选手，还有发现人工智能漏洞的科学家都属于白帽黑客。</p><p>这些白帽黑客每天都在对抗坏蛋黑客。如果你以后成为了特别厉害的程序员或者是计算机科学家，也可以成为一名酷酷的<strong>白帽黑客</strong>，保护大家的信息安全。</p><p>那说到安全呢，现在世界上还有很多公司和科学家在研究自动驾驶汽车。据说呀，如果所有人都用上了自动驾驶汽车，那么世界上就不会再有交通事故发生了。咱们下一集，就来讲讲神奇的<strong>自动驾驶</strong>，下集见！</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,45)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};